def translate_bytelandian_to_english(bytelandian_sentence, translation_map):
    translation_map = str(translation_map)
    english_sentence = ""
    for char in bytelandian_sentence:
        if char in translation_map:
            english_sentence += translation_map[ord(char) - ord('a')]
        elif char.isupper():
            english_sentence += translation_map[ord(char.lower()) - ord('a')].upper()
